package structural.bridge.sample;

public interface IColor {
    String fill();
}

package structural.bridge.sample;

import structural.bridge.sample.colors.*;
import structural.bridge.sample.shapes.*;

public class Main {
    public static void main(String[] args) {
        IColor redColor = new RedColor();
        IColor blueColor = new BlueColor();
        Shape redCircle = new Circle(redColor);
        Shape blueCircle = new Circle(blueColor);

        redCircle.draw();
        blueCircle.draw();


        IColor greenColor = new GreenColor();
        Shape redSquare = new Square(redColor);
        Shape blueSquare = new Square(blueColor);
        Shape greenSquare = new Square(greenColor);


        redSquare.draw();
        blueSquare.draw();
        greenSquare.draw();
    }
}

package structural.bridge.sample;

// Abstraction — holds a reference to the Implementor instead of extending it.
public abstract class Shape {
    protected IColor color;

    protected Shape(IColor color) {
        this.color = color;
    }

    public abstract void draw();
}

package structural.bridge.sample.colors;

import structural.bridge.sample.IColor;

public class BlueColor implements IColor {
    @Override
    public String fill() {
        return "blue";
    }
}

package structural.bridge.sample.colors;

import structural.bridge.sample.IColor;

public class GreenColor implements IColor {
    @Override
    public String fill() {
        return "green";
    }
}

package structural.bridge.sample.colors;

import structural.bridge.sample.IColor;

public class RedColor implements IColor {
    @Override
    public String fill() {
        return "red";
    }
}

package structural.bridge.sample.shapes;

import structural.bridge.sample.IColor;
import structural.bridge.sample.Shape;

public class Circle extends Shape {
    public Circle(IColor color) {
        super(color);
    }

    @Override
    public void draw() {
        System.out.println("Circle filled with " + color.fill());
    }
}

package structural.bridge.sample.shapes;

import structural.bridge.sample.IColor;
import structural.bridge.sample.Shape;

public class Square extends Shape {
    public Square(IColor color) {
        super(color);
    }

    @Override
    public void draw() {
        System.out.println("Square filled with " + color.fill());
    }
}

